                XLClass.xl_can_msg message = nativeEvent.tagData.can_Msg;
                VectorClassicCanEventFlags flags = MapClassicEventFlags(
                    nativeEvent.flags,
                    message.flags);
                receivedEvents ??= new List<VectorClassicCanEvent>(
                    Math.Min(maximumEventCount, 32));
