{
    HardwareOperationException? stopFault = null;
    try
    {
        _executionCts?.Cancel();

        if (_engine is not null)
        {
            _engine.FrameRouted -= OnEngineFrameRouted;
            _engine.EngineFaulted -= OnEngineFaulted;

